    def _make_buffer(
        self, *size: int | torch.SymInt, dtype: torch.dtype = torch.int32
    ) -> CpuGpuBuffer:
        return CpuGpuBuffer(
            *size,
            dtype=dtype,
            device=self.device,
            pin_memory=self.pin_memory,
            with_numpy=True,
        )

    def _ensure_kv_metadata_capacity(
        self, required_reqs: int, required_pages: int
    ) -> None:
        base_request_capacity = self._base_paged_kv_last_page_len.cpu.numel()
        base_page_capacity = self._base_paged_kv_indices.cpu.numel()
        if (
            required_reqs <= base_request_capacity
            and required_pages <= base_page_capacity
        ):
            self.paged_kv_indptr = self._base_paged_kv_indptr
            self.paged_kv_indptr_cpu_buffer = (
                self._base_paged_kv_indptr_cpu_buffer
            )
            self.paged_kv_indices = self._base_paged_kv_indices
            self.paged_kv_last_page_len = self._base_paged_kv_last_page_len
            return

        if (
            required_reqs <= self._overflow_request_capacity
            and required_pages <= self._overflow_page_capacity
        ):
            self.paged_kv_indptr = self._overflow_paged_kv_indptr
            self.paged_kv_indptr_cpu_buffer = (
                self._overflow_paged_kv_indptr_cpu_buffer
            )
            self.paged_kv_indices = self._overflow_paged_kv_indices
            self.paged_kv_last_page_len = (
                self._overflow_paged_kv_last_page_len
            )
            return
        if torch.cuda.is_current_stream_capturing():
            raise RuntimeError(
                "FlashInfer KV metadata buffers cannot grow during CUDA graph capture"
            )

        self._overflow_request_capacity = max(
            required_reqs,
            max(base_request_capacity, self._overflow_request_capacity) * 2,
        )
        self._overflow_page_capacity = max(
            required_pages,
            max(base_page_capacity, self._overflow_page_capacity) * 2,
        )
        self.paged_kv_indptr = self._make_buffer(
            self._overflow_request_capacity + 1
        )
        self.paged_kv_indptr_cpu_buffer = torch.zeros_like(
            self.paged_kv_indptr.cpu, pin_memory=self.pin_memory
        )
        self.paged_kv_indices = self._make_buffer(self._overflow_page_capacity)
        self.paged_kv_last_page_len = self._make_buffer(
            self._overflow_request_capacity
        )
